    function automatic int destination(input int source,input logic [31:0] random_value);
      int d;
      case(pattern)
        1: d=2*(source%3)+source/3;
        2: d=2;
        3: case(source) 0:d=1;1:d=2;2:d=5;5:d=4;4:d=3;default:d=0;endcase
        default: begin d=int'(random_value%5); if(d>=source)d++; end   // 0 uniform, 4 (sat_vc2 memory part)
      endcase
      return d;
    endfunction
    // OD-6 amendment 1 (Kalash 2026-10-20): the production router forbids LOCAL->LOCAL traffic, so a hotspot or
    // transpose source whose destination is itself generates nothing (offered stays 0; its PERF line still prints).
    function automatic bit idle_source(input int source);
      return pattern==5 || ((pattern==1 || pattern==2) && destination(source,32'd0)==source);   // N2P7: pattern 5 = no data
    endfunction
    function automatic logic [31:0] data_of(input int source,input int seq);
      return (32'(source)<<28) | ((32'(seq*193+71)&32'hfff)<<16) | 32'(seq);
    endfunction
    // Expected payload word i of generator record (s,q): a function of the record only.
    function automatic logic [31:0] word_of(input int s,input int q,input int i);
      if(rec_kind[s][q]==MSG_MEM_WR_REQ)
        return i==0 ? (REMOTE_BASE | (32'(rec_dest[s][q])<<TILE_SEL_LSB) | (32'(q)<<2)) : data_of(s,q);
      return (32'(s)<<28) | (32'(int'(rec_kind[s][q]))<<24) | (32'(i&255)<<16) | 32'(q&16'hffff);
    endfunction
    function automatic int nwords(input msg_type_e k);
      return int'(message_payload_flits(k));
    endfunction
    function automatic int vc_of(input msg_type_e k);
      return int'(message_to_vc(k));
    endfunction
    task automatic check(input bit ok,input string name);
      checks++;if(!ok)begin errors++;$display("[FAIL] %s",name);end
    endtask

    function automatic int new_record(input int s,input msg_type_e k,input int d,input bit prio);
      int q,v;
      q=nrec[s];
      if(q>=RC)begin errors++;$display("[FAIL] RECORD_OVERFLOW source=%0d",s);return -1;end
      v=vc_of(k);
      rec_kind[s][q]=k;rec_dest[s][q]=d;rec_state[s][q]=0;seen[s][q]=0;
      tgen[s][q]=cyc;taccept[s][q]=-1;tinj[s][q]=-1;tdel[s][q]=-1;
      lst[s][d][v][lst_n[s][d][v]]=q;lst_n[s][d][v]++;
      if(prio)begin pq[s][pq_wr[s]]=q;pq_wr[s]++;end else begin dq[s][dq_wr[s]]=q;dq_wr[s]++;end
      nrec[s]++;
      return q;
    endfunction
    // Event-created record (N-7.5 models): counted as offered and queued, never capped.
    task automatic event_record(input int s,input msg_type_e k,input int d);
      int q;
      offered[s]++;q=new_record(s,k,d,1);
    endtask

    function automatic bit rec_match(input int s,input int q,input msg_type_e m,input int t);
      if(rec_kind[s][q]!=m || r_nw[t]!=nwords(m))return 0;
      for(int i=0;i<r_nw[t] && i<MAXW;i++)if(r_words[t][i]!==word_of(s,q,i))return 0;
      return 1;
    endfunction

    task automatic attribute(input int t,input int s,input int q,input bit ok);
      seen[s][q]=1;tdel[s][q]=cyc;del_from[s]++;
      $display("TRACE pattern=%0d period=%0d mac=%0d kind=%0d source=%0d seq=%0d dst=%0d gen=%0d accept=%0d inj=%0d del=%0d ok=%0d",
               pattern,period,MAC_ENABLE,int'(rec_kind[s][q]),s,q,t,tgen[s][q],taccept[s][q],tinj[s][q],cyc,ok);
    endtask

    // Scoreboard: the delivered packet is matched against the generator records of
    // its (source, destination, VC) list. The expected packet is the head of that list;
    // a packet that matches no record exactly is reported against that expected record.
    task automatic scoreboard(input int t,input int s,input msg_type_e m);
      int v,n,p,k,found,dup,q,wi;
      if(s<0 || s>=6 || int'(m)>=8)begin unknown_n++;errors++;$display("[FAIL] SCOREBOARD_UNKNOWN tile=%0d source=%0d msg=%0d",t,s,int'(m));return;end
      v=vc_of(m);n=lst_n[s][t][v];p=lst_p[s][t][v];
      if(p<n && rec_match(s,lst[s][t][v][p],m,t))begin attribute(t,s,lst[s][t][v][p],1);lst_p[s][t][v]=p+1;return;end
      found=-1;for(k=p+1;k<n && found<0;k++)if(rec_match(s,lst[s][t][v][k],m,t))found=k;
      if(found>=0)begin attribute(t,s,lst[s][t][v][found],1);lst_p[s][t][v]=found+1;return;end   // skipped records stay unseen -> MISSING
      dup=-1;for(k=0;k<p && dup<0;k++)if(rec_match(s,lst[s][t][v][k],m,t))dup=k;
      if(dup>=0)begin duplicate_n++;errors++;$display("[FAIL] SCOREBOARD_DUPLICATE source=%0d seq=%0d dst=%0d",s,lst[s][t][v][dup],t);return;end
      if(p>=n)begin unknown_n++;errors++;$display("[FAIL] SCOREBOARD_UNKNOWN tile=%0d source=%0d msg=%0d",t,s,int'(m));return;end
      q=lst[s][t][v][p];mismatch_n++;errors++;
      if(rec_kind[s][q]!=m)$display("[FAIL] SCOREBOARD_TYPE source=%0d seq=%0d dst=%0d exp=%0d got=%0d",s,q,t,int'(rec_kind[s][q]),int'(m));
      else if(r_nw[t]!=nwords(m))$display("[FAIL] SCOREBOARD_LENGTH source=%0d seq=%0d dst=%0d exp=%0d got=%0d",s,q,t,nwords(m),r_nw[t]);
      else begin
        wi=0;while(wi<r_nw[t]-1 && r_words[t][wi]===word_of(s,q,wi))wi++;
        if(m==MSG_MEM_WR_REQ && wi==0)$display("[FAIL] SCOREBOARD_ADDRESS source=%0d seq=%0d dst=%0d exp=%08h got=%08h",s,q,t,word_of(s,q,0),r_words[t][0]);
        else $display("[FAIL] SCOREBOARD_PAYLOAD source=%0d seq=%0d dst=%0d word=%0d exp=%08h got=%08h",s,q,t,wi,word_of(s,q,wi),r_words[t][wi]);
      end
      attribute(t,s,q,0);lst_p[s][t][v]=p+1;
    endtask

    // Request completion at tile t (payload-last with MAC off, trailing MAC with MAC on).
    task automatic complete(input int t);
      int s;msg_type_e m;
      s=r_src[t];m=r_msg[t];
      scoreboard(t,s,m);
      if(m==MSG_MEM_WR_REQ)begin   // independent memory-response stand-in: every received request
        if(resp_wr[t]>=RQ)begin errors++;$display("[FAIL] RESP_QUEUE_OVERFLOW tile=%0d",t);end
        else begin response_dest[t][resp_wr[t]]=r_srcc[t];response_ctl[t][resp_wr[t]]=r_ctl[t]&11'h001;resp_wr[t]++;end
      end
      if(BUILD==BUILD_N75_SECOND_CHALLENGE)begin
        if(m==MSG_ATTEST_CHALLENGE && t!=ROT)begin
          if(!ep_busy[t])begin
            ep_busy[t]=1;ep_until[t]=cyc+CRYPTO_LAT;ep_peer[t]=s;ep_served[t]++;
            if(t==EP_TILE && ep_served[t]==1 && !spoof_sent)begin spoof_sent=1;event_record(ROT,MSG_ATTEST_CHALLENGE,EP_TILE);end
          end else begin ep_drained[t]++;ep_drained_src[t]=s;end
        end
        if(m==MSG_ATTEST_RESPONSE && t==ROT)begin
          rot_resp++;rot_out--;if(s==EP_TILE)rot_resp_from_ep++;
          if(s==EP_TILE && rot_issued<2)begin
            event_record(ROT,MSG_ATTEST_CHALLENGE,EP_TILE);rot_issued++;rot_out++;if(rot_out>rot_max_out)rot_max_out=rot_out;
          end
        end
        if(m==MSG_ATTEST_RESPONSE && t==ROT && rot_resp>rot_issued)resp_to_spoof++;
      end
      if(BUILD==BUILD_N2P7)begin   // control loop 4 -> 3 CHALLENGE, 3 -> 4 RESPONSE, 4 -> 3 GRANT
        if(m==MSG_ATTEST_CHALLENGE && t==EP_TILE && s==ROT)event_record(EP_TILE,MSG_ATTEST_RESPONSE,ROT);
        if(m==MSG_ATTEST_RESPONSE && t==ROT && s==EP_TILE)event_record(ROT,MSG_ATTEST_GRANT,EP_TILE);
        if(m==MSG_ATTEST_GRANT && t==EP_TILE && s==ROT && loop_busy)begin
          int r;
          r=cyc-loop_t0;loop_busy=0;loops_done++;rtt_sum+=r;
          if(rtt_min<0 || r<rtt_min)rtt_min=r;
          if(r>rtt_max)rtt_max=r;
        end
      end
    endtask

    function automatic bit resp_eligible(input int t);
      return resp_rd[t]<resp_wr[t] && !(BUILD==BUILD_CTRL_STALL && stall_on && t==STALL_TILE);
    endfunction
    function automatic bit pending();
      for(int t=0;t<6;t++)if(ds[t]!=0 || dq_rd[t]<dq_wr[t] || pq_rd[t]<pq_wr[t] || resp_rd[t]<resp_wr[t] ||
        ep_busy[t] || accepted[t]!=del_from[t] || mem_accepted[t]!=responses[t])return 1;
      return 0;
    endfunction
    function automatic bit hw_idle();
      for(int t=0;t<6;t++)if(!rq_idle[t] || !l_idle[t] || tx_busy[t] || rx_busy[t] || slot_busy[t])return 0;
      return 1;
    endfunction
    function automatic bit credits_back();
      for(int t=0;t<6;t++)if(!cr_ok[t])return 0;
      return 1;
    endfunction
    function automatic bit drained();
      return !pending() && hw_idle() && credits_back();
    endfunction
    function automatic logic [7:0] mask_of(input int what);
      logic [7:0] m;m=0;
      for(int t=0;t<6;t++)case(what)
        0: if(ds[t]!=0)m[t]=1;
        1: if(dq_rd[t]<dq_wr[t] || pq_rd[t]<pq_wr[t])m[t]=1;
        2: if(resp_rd[t]<resp_wr[t])m[t]=1;
        default: if(slot_busy[t])m[t]=1;
      endcase
      return m;
    endfunction
    task automatic liveness_line(input string reason);
      int first,inflight;first=-1;inflight=0;
      for(int t=0;t<6;t++)begin inflight+=accepted[t]-del_from[t];
        if(first<0 && (ds[t]!=0 || dq_rd[t]<dq_wr[t] || pq_rd[t]<pq_wr[t] || resp_rd[t]<resp_wr[t] || ep_busy[t] || accepted[t]!=del_from[t] || mem_accepted[t]!=responses[t]))first=t;end
      live_fired=1;errors++;
      $display("LIVENESS_FIRED case=%s pattern=%0d period=%0d mac=%0d cycle=%0d reason=%s window=%0d first_pending_tile=%0d ds_mask=%02h queue_mask=%02h resp_backlog_mask=%02h slot_mask=%02h inflight=%0d",
               build_name(),pattern,period,MAC_ENABLE,cyc,reason,LIVE_WINDOW,first,mask_of(0),mask_of(1),mask_of(2),mask_of(3),inflight);
    endtask

    //-------------------------------------------------------------------------
    // Read-only monitors.
    //-------------------------------------------------------------------------
    for(genvar g=0;g<6;g++) begin: PM
      always @(posedge clk) if(!rst) begin
        if(m_in_valid[g]&&m_in_ready[g])link_flits[g]++;
        if(tx_busy[g])ni_busy_cycles[g]++;
        if(!mesh.GEN_R[g].r.eject_empty)eject_cycles[g]++;
        // noc_router exposes per-port/VC full flags only as named scalars
        // (full_<port>_vc<v>); there is no fifo_full[] array.
        full_cycles[g][0]+=int'(mesh.GEN_R[g].r.full_north_vc0)+int'(mesh.GEN_R[g].r.full_south_vc0)+int'(mesh.GEN_R[g].r.full_east_vc0)+int'(mesh.GEN_R[g].r.full_west_vc0)+int'(mesh.GEN_R[g].r.full_local_vc0);
        full_cycles[g][1]+=int'(mesh.GEN_R[g].r.full_north_vc1)+int'(mesh.GEN_R[g].r.full_south_vc1)+int'(mesh.GEN_R[g].r.full_east_vc1)+int'(mesh.GEN_R[g].r.full_west_vc1)+int'(mesh.GEN_R[g].r.full_local_vc1);
        full_cycles[g][2]+=int'(mesh.GEN_R[g].r.full_north_vc2)+int'(mesh.GEN_R[g].r.full_south_vc2)+int'(mesh.GEN_R[g].r.full_east_vc2)+int'(mesh.GEN_R[g].r.full_west_vc2)+int'(mesh.GEN_R[g].r.full_local_vc2);
        for(int v=0;v<3;v++)
          for(int p=0;p<5;p++)
            if(mesh.GEN_R[g].r.u_credit_control.credit_count[p][v]==0)credit_stalls[g][v]++;
      end
    end

    //-------------------------------------------------------------------------
    // Tile drive (negedge): request/response valid and payload words.
    //-------------------------------------------------------------------------
    always @(negedge clk) if(!rst) begin
      for(int t=0;t<6;t++)begin
        tx_valid[t]=ds[t]==1;
        tx_pvalid[t]=ds[t]==2;
        if(ds[t]==2)begin
          tx_pdata[t]=word_of(t,cur_seq[t],pw[t]);
          if(BUILD==BUILD_CTRL_CORRUPT && t==CORRUPT_SRC && cur_seq[t]==CORRUPT_SEQ && pw[t]==CORRUPT_WORD)
            tx_pdata[t]=tx_pdata[t]^(32'h1<<CORRUPT_BIT);
        end
      end
    end

    //-------------------------------------------------------------------------
    // Generator, tile TX, injection/ejection observation, RX, liveness (posedge).
    // cyc = cycle index within the point (0 = first cycle after reset release).
    //-------------------------------------------------------------------------
    always @(posedge clk) if(!rst)begin
      bit prog;
      prog=0;
      if(BUILD==BUILD_CTRL_STALL && cyc==STALL_AT && !stall_on && generation_on)begin
        stall_on=1;ctrl_applied=1;
        $display("CONTROL_APPLIED kind=stall_consumption scope=memory_service tile=%0d cycle=%0d",STALL_TILE,cyc);
      end
      if(BUILD==BUILD_N75_SECOND_CHALLENGE && generation_on)begin
        if(cyc==CH1_AT && rot_issued==0)begin event_record(ROT,MSG_ATTEST_CHALLENGE,EP_TILE);rot_issued=1;rot_out=1;rot_max_out=1;end
      end
      if(BUILD==BUILD_N2P7 && generation_on && cyc<GEN_CYCLES && !loop_busy && loops_started<LOOP_MAX)begin
        event_record(ROT,MSG_ATTEST_CHALLENGE,EP_TILE);loop_busy=1;loop_t0=cyc;loops_started++;
      end
      for(int t=0;t<6;t++)begin
        int q,k_dest;msg_type_e k;
        // ---- generator (rate model; never sees DUT values)
        if(generation_on && cyc<GEN_CYCLES && cyc%period==t%period && !idle_source(t))begin
          offered[t]++;
          if(gen_n[t]<CAP)begin
            rng[t]=rng[t]*32'd1664525+32'd1013904223;
            k=MSG_MEM_WR_REQ;k_dest=destination(t,rng[t]);
            if(pattern==4)begin
              // P7 (R7.4): attestation only 4 -> 3 CHALLENGE and 3 -> 4 RESPONSE; tiles 0, 1, 2, 5 send data only
              if(t==ROT)begin k=MSG_ATTEST_CHALLENGE;k_dest=EP_TILE;end
              else if(t==EP_TILE && gen_n[t]%2==0)begin k=MSG_ATTEST_RESPONSE;k_dest=ROT;end
            end
            q=new_record(t,k,k_dest,0);gen_n[t]++;
          end else drops[t]++;
        end
        // ---- N-7.5 endpoint crypto completion
        if(BUILD==BUILD_N75_SECOND_CHALLENGE && ep_busy[t] && cyc>=ep_until[t])begin
          ep_busy[t]=0;event_record(t,MSG_ATTEST_RESPONSE,ep_peer[t]);
        end
        // ---- tile TX: responses first, then priority (event) records, then data records
        case(ds[t])
          0: if(resp_eligible(t))begin
               cur_resp[t]=1;tx_dest[t]=response_dest[t][resp_rd[t]];tx_control[t]=response_ctl[t][resp_rd[t]];
               tx_msg[t]=MSG_MEM_WR_RESP;ds[t]=1;
             end else if(pq_rd[t]<pq_wr[t])begin
               cur_resp[t]=0;cur_prio[t]=1;cur_seq[t]=pq[t][pq_rd[t]];
               tx_dest[t]=tile_to_coord(tile_id_e'(rec_dest[t][cur_seq[t]]));tx_control[t]=11'h780;tx_msg[t]=rec_kind[t][cur_seq[t]];ds[t]=1;
             end else if(dq_rd[t]<dq_wr[t])begin
               q=dq[t][dq_rd[t]];
               if(BUILD==BUILD_CTRL_DROP && t==DROP_SRC && q==DROP_SEQ && !ctrl_applied)begin
                 dq_rd[t]++;rec_state[t][q]=2;ctrl_applied=1;
                 $display("CONTROL_APPLIED kind=drop_packet scope=generator_to_ni source=%0d seq=%0d cycle=%0d",t,q,cyc);
               end else begin
                 cur_resp[t]=0;cur_prio[t]=0;cur_seq[t]=q;
                 tx_dest[t]=tile_to_coord(tile_id_e'(rec_dest[t][q]));tx_control[t]=11'h780;tx_msg[t]=rec_kind[t][q];ds[t]=1;
               end
             end
          1: if(tx_valid[t]&&tx_ready[t])begin
               prog=1;
               if(acc_wr[t]-acc_rd[t]>=ACQ)begin errors++;$display("[FAIL] ACCEPT_QUEUE_OVERFLOW tile=%0d",t);end
               accq[t][acc_wr[t]%ACQ]=cur_resp[t]?-1:cur_seq[t];acc_wr[t]++;
               if(cur_resp[t])begin resp_rd[t]++;ds[t]=0;end
               else begin
                 q=cur_seq[t];
                 if(cur_prio[t])pq_rd[t]++;else dq_rd[t]++;
                 rec_state[t][q]=1;taccept[t][q]=cyc;accepted[t]++;
                 if(rec_kind[t][q]==MSG_MEM_WR_REQ)mem_accepted[t]++;
                 nw_tx[t]=nwords(rec_kind[t][q]);pw[t]=0;ds[t]=nw_tx[t]>0?2:0;
               end
             end else if(!cur_resp[t] && rec_kind[t][cur_seq[t]]==MSG_MEM_WR_REQ && (resp_eligible(t) || pq_rd[t]<pq_wr[t]))
               ds[t]=0;   // withdraw a slot-blocked request so a response / event record can go first
          2: if(tx_pvalid[t]&&tx_pready[t])begin
               prog=1;
               if(BUILD==BUILD_CTRL_CORRUPT && t==CORRUPT_SRC && cur_seq[t]==CORRUPT_SEQ && pw[t]==CORRUPT_WORD && !ctrl_applied)begin
                 ctrl_applied=1;
                 $display("CONTROL_APPLIED kind=corrupt_payload scope=tile_tx source=%0d seq=%0d word=%0d bit=%0d cycle=%0d",t,cur_seq[t],pw[t],CORRUPT_BIT,cyc);
               end
               if(pw[t]>=nw_tx[t]-1)ds[t]=0;else pw[t]++;
             end
        endcase
        if(tx_error[t])begin tx_error_events++;errors++;$display("[FAIL] UNEXPECTED_TX_ERROR tile=%0d",t);end
        // ---- injection (HEAD/HEAD_TAIL into the mesh, NI order == accept order)
        if(m_in_valid[t]&&m_in_ready[t])begin
          prog=1;
          if(m_in_flit[t].flit_type==FLIT_HEAD || m_in_flit[t].flit_type==FLIT_HEAD_TAIL)begin
            if(acc_rd[t]<acc_wr[t])begin
              q=accq[t][acc_rd[t]%ACQ];acc_rd[t]++;
              if(q>=0)begin tinj[t][q]=cyc;injected[t]++;end
            end else begin errors++;$display("[FAIL] INJECT_WITHOUT_ACCEPT tile=%0d",t);end
          end
        end
        if(m_out_valid[t]&&m_out_ready[t])prog=1;
        // ---- RX
        if(rx_hv[t]&&rx_ready[t])begin
          prog=1;
          r_src[t]=int'(rx_src[t].y)*3+int'(rx_src[t].x);r_srcc[t]=rx_src[t];r_msg[t]=rx_msg[t];r_ctl[t]=rx_ctl[t];r_nw[t]=0;
          if(rx_msg[t]==MSG_MEM_WR_RESP)responses[t]++;
        end
        if(rx_pv[t]&&rx_ready[t])begin
          prog=1;
          if(r_nw[t]<MAXW)r_words[t][r_nw[t]]=rx_pd[t];
          r_nw[t]++;
          if(p7_mac_flits(r_msg[t])==0 && rx_pl[t] && r_msg[t]!=MSG_MEM_WR_RESP)complete(t);
        end
        if(rx_mv[t])begin
          prog=1;
          if(r_msg[t]!=MSG_MEM_WR_RESP)complete(t);
        end
        if(rx_abort[t]||rx_perr[t]||rx_lerr[t])begin contain_events++;errors++;$display("[FAIL] UNEXPECTED_CONTAINMENT tile=%0d cycle=%0d",t,cyc);end
      end
      // ---- liveness monitor: no tile/mesh-boundary handshake for LIVE_WINDOW cycles while work is pending
      if(live_armed && !live_fired)begin
        if(prog || !pending())live_idle=0;else live_idle++;
        if(live_idle>=LIVE_WINDOW)liveness_line("no_progress");
      end
      cyc++;
    end

    //-------------------------------------------------------------------------
    // Point sequencing.
    //-------------------------------------------------------------------------
    task automatic clear_point(input int pat,input int per);
      pattern=pat;period=per;
      generation_on=0;live_armed=0;live_fired=0;live_idle=0;ctrl_applied=0;stall_on=0;
      contain_events=0;tx_error_events=0;duplicate_n=0;mismatch_n=0;unknown_n=0;
      rot_issued=0;rot_out=0;rot_max_out=0;rot_resp=0;rot_resp_from_ep=0;spoof_sent=0;resp_to_spoof=0;
      loops_started=0;loops_done=0;loop_t0=0;rtt_sum=0;rtt_min=-1;rtt_max=0;loop_busy=0;
      for(int t=0;t<6;t++)begin
        offered[t]=0;gen_n[t]=0;drops[t]=0;nrec[t]=0;accepted[t]=0;mem_accepted[t]=0;injected[t]=0;del_from[t]=0;responses[t]=0;
        dq_rd[t]=0;dq_wr[t]=0;pq_rd[t]=0;pq_wr[t]=0;resp_rd[t]=0;resp_wr[t]=0;acc_rd[t]=0;acc_wr[t]=0;
        ds[t]=0;cur_seq[t]=0;cur_resp[t]=0;cur_prio[t]=0;pw[t]=0;nw_tx[t]=0;r_src[t]=0;r_srcc[t]='0;r_nw[t]=0;r_msg[t]=MSG_MEM_WR_REQ;r_ctl[t]=0;
        ep_busy[t]=0;ep_until[t]=0;ep_peer[t]=0;ep_served[t]=0;ep_drained[t]=0;ep_drained_src[t]=-1;
        tx_valid[t]=0;tx_pvalid[t]=0;tx_pdata[t]=0;tx_dest[t]='0;tx_msg[t]=MSG_MEM_WR_REQ;tx_control[t]=0;tx_mac[t]=0;
        rx_ready[t]=1;st_clr[t]=0;rng[t]=SEED+32'(t);link_flits[t]=0;ni_busy_cycles[t]=0;eject_cycles[t]=0;
        for(int v=0;v<3;v++)begin full_cycles[t][v]=0;credit_stalls[t][v]=0;end
        for(int d=0;d<6;d++)for(int v=0;v<3;v++)begin lst_n[t][d][v]=0;lst_p[t][d][v]=0;end
        for(int q=0;q<RC;q++)begin seen[t][q]=0;rec_state[t][q]=0;tgen[t][q]=-1;taccept[t][q]=-1;tinj[t][q]=-1;tdel[t][q]=-1;end
      end
    endtask

    task automatic start_point(input int pat,input int per);
      rst=1;clear_point(pat,per);
      repeat(5)@(negedge clk);
      cyc=0;rst=0;generation_on=1;live_armed=1;
    endtask

    task automatic run_point(input int pat,input int per);
      int wait_cycles,o,qd,cd,a,ma,inj,dl,rs,miss,unsent,shown,e0;
      bit cred,idle,dr;
      string id,vd;
      e0=errors;
      start_point(pat,per);
      repeat(GEN_CYCLES)@(negedge clk);
      generation_on=0;
      wait_cycles=0;
      while(!drained() && !live_fired && wait_cycles<DRAIN)begin @(negedge clk);wait_cycles++;end
      dr=drained();
      if(!dr && !live_fired)liveness_line("drain_bound");
      cred=credits_back();idle=hw_idle();
      live_armed=0;
      // MISSING: scan every generator record that left the TB queue (accepted by the NI or
      // removed by a control) and was never delivered. Records still queued are UNSENT.
      miss=0;unsent=0;shown=0;
      for(int s=0;s<6;s++)for(int q=0;q<nrec[s];q++)begin
        if(rec_state[s][q]==0)unsent++;
        else if(!seen[s][q])begin
          miss++;
          if(shown<16)begin shown++;errors++;$display("[FAIL] SCOREBOARD_MISSING source=%0d seq=%0d dst=%0d kind=%0d",s,q,rec_dest[s][q],int'(rec_kind[s][q]));end
        end
      end
      if(miss>shown)begin errors++;$display("[FAIL] SCOREBOARD_MISSING_MORE count=%0d",miss-shown);end
      o=0;qd=0;cd=0;a=0;ma=0;inj=0;dl=0;rs=0;
      for(int t=0;t<6;t++)begin
        o+=offered[t];qd+=nrec[t];cd+=drops[t];a+=accepted[t];ma+=mem_accepted[t];inj+=injected[t];dl+=del_from[t];rs+=responses[t];
        $display("PERF pattern=%0d period=%0d mac=%0d tile=%0d offered=%0d queued=%0d accepted=%0d injected=%0d delivered=%0d cap_drops=%0d responses=%0d elapsed=%0d link_flits=%0d ni_busy=%0d eject_busy=%0d",
                 pattern,period,MAC_ENABLE,t,offered[t],nrec[t],accepted[t],injected[t],del_from[t],drops[t],responses[t],cyc,link_flits[t],ni_busy_cycles[t],eject_cycles[t]);
        for(int v=0;v<3;v++)$display("MONITOR pattern=%0d period=%0d mac=%0d tile=%0d vc=%0d fifo_full_port_cycles=%0d credit_zero_port_cycles=%0d",pattern,period,MAC_ENABLE,t,v,full_cycles[t][v],credit_stalls[t][v]);
      end
      id=$sformatf("case=%s pattern=%0d period=%0d mac=%0d",build_name(),pattern,period,MAC_ENABLE);
      // 14 point checks (the count is independent of traffic, MAC mode and outcome).
      check(o==qd+cd,{"PERF_OFFERED ",id});
      check(qd==a,{"PERF_ACCEPTED ",id});
      check(a==inj,{"PERF_INJECTED ",id});
      check(inj==dl,{"PERF_DELIVERED ",id});
      check(rs==ma,{"PERF_RESPONSES ",id});
      check(miss==0,{"PERF_NO_MISSING ",id});
      check(duplicate_n==0,{"PERF_NO_DUPLICATE ",id});
      check(mismatch_n==0,{"PERF_NO_MISMATCH ",id});
      check(unknown_n==0,{"PERF_NO_UNKNOWN ",id});
      check(cred,{"PERF_CREDITS_RETURNED ",id});
      check(idle,{"PERF_IDLE_AFTER_DRAIN ",id});
      check(dr && wait_cycles<=DRAIN,{"PERF_BOUNDED_DRAIN ",id});
      check(!live_fired,{"PERF_NO_LIVENESS ",id});
      check(contain_events==0 && tx_error_events==0,{"PERF_NO_CONTAINMENT ",id});
      if(errors==e0) vd="OK"; else vd="FAIL";
      $display("POINT case=%s pattern=%0d period=%0d mac=%0d offered=%0d queued=%0d cap_drops=%0d accepted=%0d injected=%0d delivered=%0d responses=%0d mem_accepted=%0d missing=%0d unsent=%0d duplicate=%0d mismatched=%0d unknown=%0d credits_returned=%0d idle_after_drain=%0d drain_cycles=%0d verdict=%s transport=%s w=%0d wde=%0d seed=0x%08h n_out=%0d tool=%s",
               build_name(),pattern,period,MAC_ENABLE,o,qd,cd,a,inj,dl,rs,ma,miss,unsent,duplicate_n,mismatch_n,unknown_n,cred,idle,wait_cycles,
               vd,TRANSPORT,W,WDE,SEED,N_OUTSTANDING,TOOL);
    endtask

    // N-7.5 reset during traffic: phase A runs uniform 1/4 traffic and asserts reset at
    // RESET_AT with packets in flight; the fabric must be idle with all credits after
    // RESET_LEN reset cycles. Phase B (run_point) then reruns the full point.
    task automatic reset_phase_a(input int pat,input int per);
      int a,d;
      start_point(pat,per);
      repeat(RESET_AT)@(negedge clk);
      rst_had_traffic=!hw_idle();
      a=0;d=0;for(int t=0;t<6;t++)begin a+=accepted[t];d+=del_from[t];end
      rst=1;generation_on=0;live_armed=0;
      repeat(RESET_LEN)@(negedge clk);
      begin bit ri,li,ni;ri=1;li=1;ni=1;
        for(int t=0;t<6;t++)begin if(!rq_idle[t]||!cr_ok[t])ri=0;if(!l_idle[t])li=0;if(tx_busy[t]||rx_busy[t]||slot_busy[t])ni=0;end
        check(rst_had_traffic,"N75_RESET_HAD_TRAFFIC");
        check(ri,"N75_RESET_ROUTERS_IDLE");
        check(li,"N75_RESET_LINKS_IDLE");
        check(ni,"N75_RESET_NI_IDLE");
        $display("N75_RESET phase=A pattern=%0d period=%0d mac=%0d reset_at=%0d reset_len=%0d had_traffic=%0d accepted=%0d delivered=%0d inflight=%0d routers_idle=%0d links_idle=%0d ni_idle=%0d",
                 pat,per,MAC_ENABLE,RESET_AT,RESET_LEN,rst_had_traffic,a,d,a-d,ri,li,ni);
      end
    endtask

    initial begin
      $display("CONFIG: TOP=tb_noc_perf_p7 CASE=%s POINTS=%0d MAC_FLITS=%0d SEED=305419896 CLOCK_NS=20 W=%0d WDE=%0d N_OUTSTANDING=%0d TRANSPORT=%s TOOL=%s WARMUP=%0d MEASURE=%0d DRAIN=%0d CAP=%0d LIVE_WINDOW=%0d",
               build_name(),BUILD==BUILD_PERF?28:BUILD==BUILD_N2P7?7:1,MAC_FLITS,W,WDE,N_OUTSTANDING,TRANSPORT,TOOL,WARMUP,MEASURE,DRAIN,CAP,LIVE_WINDOW);
      rst=1;cyc=0;clear_point(0,64);
      check(N_OUTSTANDING==2,"CFG_N_OUTSTANDING");
      case(BUILD)
        BUILD_CTRL_CORRUPT: begin
          $display("CONTROL kind=corrupt_payload target_source=%0d target_seq=%0d word=%0d bit=%0d",CORRUPT_SRC,CORRUPT_SEQ,CORRUPT_WORD,CORRUPT_BIT);
          run_point(0,16);
        end
        BUILD_CTRL_DROP: begin
          $display("CONTROL kind=drop_packet target_source=%0d target_seq=%0d scope=generator_to_ni",DROP_SRC,DROP_SEQ);
          run_point(0,16);
        end
        BUILD_CTRL_STALL: begin
          $display("CONTROL kind=stall_consumption target_tile=%0d from_cycle=%0d scope=memory_service",STALL_TILE,STALL_AT);
          run_point(2,16);
        end
        BUILD_N75_SAT_VC2: begin
          int att,mem,ad,md,vc2z;
          run_point(4,1);
          att=0;mem=0;ad=0;md=0;vc2z=0;
          for(int s=0;s<6;s++)for(int q=0;q<nrec[s];q++)begin
            if(rec_kind[s][q]==MSG_MEM_WR_REQ)begin mem++;if(seen[s][q])md++;end else begin att++;if(seen[s][q])ad++;end
          end
          for(int t=0;t<6;t++)vc2z+=credit_stalls[t][2];
          check(vc2z>0,"N75_VC2_SATURATED");
          check(ad==att,"N75_VC2_ATT_DELIVERED");
          check(md==mem,"N75_VC2_MEM_DELIVERED");
          $display("N75_SAT_VC2 mac=%0d att_queued=%0d att_delivered=%0d mem_queued=%0d mem_delivered=%0d vc2_credit_zero_port_cycles=%0d",MAC_ENABLE,att,ad,mem,md,vc2z);
        end
        BUILD_N75_RESET: begin
          reset_phase_a(4,4);
          run_point(4,4);
        end
        BUILD_N75_SECOND_CHALLENGE: begin
          int dr_other;
          run_point(0,16);
          dr_other=0;for(int t=0;t<6;t++)if(t!=EP_TILE)dr_other+=ep_drained[t];
          check(rot_resp==2 && rot_resp_from_ep==2,"N75_SC_TWO_RESPONSES");
          check(ep_drained[EP_TILE]==1 && ep_drained_src[EP_TILE]==ROT && dr_other==0,"N75_SC_EXTRA_DRAINED");
          check(resp_to_spoof==0,"N75_SC_NO_RESPONSE_TO_EXTRA");
          check(rot_max_out==1 && rot_issued==2,"N75_SC_ONE_OUTSTANDING");
          check(ep_served[EP_TILE]==2 && !ep_busy[EP_TILE],"N75_SC_ENDPOINT_DONE");
          $display("N75_SECOND_CHALLENGE mac=%0d rot_issued=%0d rot_responses=%0d rot_max_outstanding=%0d ep_served=%0d ep_drained=%0d ep_drained_src=%0d responses_to_extra=%0d",
                   MAC_ENABLE,rot_issued,rot_resp,rot_max_out,ep_served[EP_TILE],ep_drained[EP_TILE],ep_drained_src[EP_TILE],resp_to_spoof);
        end
        BUILD_N2P7: begin
          int pats[7],pers[7];
          pats='{5,0,0,0,2,2,2};pers='{64,64,8,1,64,8,1};
          for(int i=0;i<7;i++)begin
            run_point(pats[i],pers[i]);
            check(loops_done>=1 && loops_done==loops_started,$sformatf("N2P7_CTRL_LOOP pattern=%0d period=%0d",pats[i],pers[i]));
            $display("N2P7_CTRL pattern=%0d period=%0d loops=%0d started=%0d rtt_min=%0d rtt_max=%0d rtt_mean=%0d",
                     pats[i],pers[i],loops_done,loops_started,rtt_min,rtt_max,loops_done>0?rtt_sum/loops_done:-1);
          end
        end
        default: for(int pat=0;pat<4;pat++)for(int rate=0;rate<7;rate++)run_point(pat,64>>rate);
      endcase
      if(BUILD==BUILD_CTRL_CORRUPT || BUILD==BUILD_CTRL_DROP || BUILD==BUILD_CTRL_STALL)
        $display("CONTROL_SUMMARY case=%s applied=%0d",build_name(),ctrl_applied);
      $display("CHECKS : %0d",checks);$display("ERRORS : %0d",errors);$display("RESULT : %s",errors==0?"PASS":"FAIL");$finish;
    end
    initial begin #150ms;$fatal(1,"TB_TIMEOUT perf bench");end
endmodule
